{
  "journeyId": "{{ij_mg_journey_id}}",
  "order": 1,
  "name": "MG behaviour tick only",
  "description": "BehaviourMetricTick-only: acceptanceRate>=1 AND cancellationRate<=50 (no ride vars)",
  "conditionType": "AcceptanceRate",
  "conditionOperator": "GTE",
  "conditionValue": 1,
  "conditionLogic": {
    "and": [
      {
        ">=": [
          {
            "var": "acceptanceRate"
          },
          1
        ]
      },
      {
        "<=": [
          {
            "var": "cancellationRate"
          },
          50
        ]
      }
    ]
  },
  "rewardType": "Coins",
  "rewardValue": 15
}

{
  "journeyId": "{{ij_mg_journey_id}}",
  "order": 2,
  "name": "MG JsonLogic ride+behaviour",
  "description": "Ride-end bag: ridesCompleted>=1 AND earnings>=1 AND acceptanceRate>=1 AND cancellationRate<=50",
  "conditionType": "RideCompleted",
  "conditionOperator": "GTE",
  "conditionValue": 1,
  "conditionLogic": {
    "and": [
      {
        ">=": [
          {
            "var": "ridesCompleted"
          },
          1
        ]
      },
      {
        ">=": [
          {
            "var": "earnings"
          },
          1
        ]
      },
      {
        ">=": [
          {
            "var": "acceptanceRate"
          },
          1
        ]
      },
      {
        "<=": [
          {
            "var": "cancellationRate"
          },
          50
        ]
      }
    ]
  },
  "rewardType": "Coins",
  "rewardValue": 25
}

{
  "journeyId": "{{ij_mg_journey_id}}",
  "order": 3,
  "name": "MG exit gate",
  "description": "Exit gate: conditionLogic ridesCompleted<1; disqualifyIfConditionNotMet=true \u2192 False after ride Disqualifies",
  "conditionType": "RideCompleted",
  "conditionOperator": "GTE",
  "conditionValue": 0,
  "conditionLogic": {
    "<": [
      {
        "var": "ridesCompleted"
      },
      1
    ]
  },
  "rewardType": "NoReward",
  "rewardValue": null,
  "disqualifyIfConditionNotMet": true
}
